<%_ /* <stat_data> */
// Early output stays data when the host performs its later template/macro pass.
function dlhBudgetSafeJSON(value){
 return JSON.stringify(value).replace(/"(?:\\.|[^"\\])*"/g,function(token){
  return token.replace(/[<>{}]/g,function(c){return '\\u'+c.charCodeAt(0).toString(16).padStart(4,'0');});
 });
}
function dlhBudgetSafeBrief(text){
 if(typeof text!=='string')throw Error('剧情记忆简报不是文本，预算前渲染已停止');
 const output=text.replace(/<\x25|\x7b\x7b|\x7d\x7d/g,function(token){return Array.from(token,c=>'\\u'+c.charCodeAt(0).toString(16).padStart(4,'0')).join('');});
 if(Array.from(output).length>2400)throw Error('剧情记忆简报转义后超出2400字符；请核对含模板符号的资料，不会截断或清空事实');
 return output;
}
_%>
【当前变量：正文只读视图】
以下JSON保留人物、关系、生死、在场、物品数量与限制、武学名称/品级/熟练度/特点、当前资源、剧情进度、日程、制作及同行事实。完整战斗定义、数值面板、生成缓存、历史账本、随机种子和引擎存档不送正文；已定义招式、成长条件、悟学条件、已知战斗余量仅为只读摘要，不是新增存档字段。制作仅显示当前工序摘要，完成、失败和取消的历史工单留在本地；待承接结果由HUD_RECORD分批提供，须实际叙述后签收。已知方案是只读工艺摘要，完整配方供本地工坊和专门请求使用。未完成制作不展示预掷结果。完整定义仍在真实MVU中，前端与专门生成API照常读取；此视图不用于存档回写。 装备只读外观、用途与持有位置。交手只读状态概况与实际效果，修行只读当前进度与限制。日历只列待承接行程，NPC余量按当前相关人物提供。
未展示不等于不存在；禁止据此remove、清空、重建或整段replace主角/世界/战斗状态/成长/制作等父对象。只对实际发生、正文有权限的叶子写JSONPatch；新增独立输入用新稳定标识，已有记录不可按显示缺项重置。路径段含“/”写~1，含“~”写~0。派生结算依前端结果；HUD_RECORD、CRAFTING_RECORD、COMPANION_RECORD及BATTLE_RECORD依本轮实际收到的记录承接，不能只凭看见任务就提前确认承接。

感悟仅列最近五条已核验结算摘要及收藏，待核验原输入保留纠错证据；技法与见闻按当前人物、地点、话题选择完整条目，目录和全文各有预算与未展开计数。未展开原文仍在本地，禁止由标题编造条件或把只读摘要写回。

