<%_ {
/* Read-only crafting projections. Real tasks, recipes and receipts are never changed. */
const DLH_BATTLE_REPORT_DISPLAY = (() => {
  const prefix = 'BATTLE_RECORD:';
  const actorStats = /;气血=\d+(?:\.\d+)?\/\d+(?:\.\d+)?(?:;较开战损失=\d+(?:\.\d+)?)?/g;
  const injury = row => row?.类型 === '重创留伤' || String(row?.标识 ?? '').endsWith('/tianmo/overload');

  function executed(result, kind, tail, actor) {
    return result === '胜' && kind !== '切磋' && tail === '击杀' && actor.side === 'R' && actor.hp <= 0;
  }

  function consequences(actors, result, kind, tail) {
    return actors.flatMap(actor => (actor.battleConsequences || []).filter(row =>
      !injury(row) || !executed(result, kind, tail, actor)));
  }

  function field(text, key, array = false) {
    const value = new RegExp('(?:^BATTLE_RECORD:|\\|)' + key + (array ? '=\\[([^\\]]*)\\]' : '=([^|]*)'));
    return value.exec(text)?.[1] || '';
  }

  function actors(text, key) {
    return field(text, key, true).replace(actorStats, '').split(';').filter(Boolean).map(entry => {
      const separator = entry.lastIndexOf(':');
      return separator < 0 ? {name:entry, state:''} : {name:entry.slice(0, separator), state:entry.slice(separator + 1)};
    });
  }

  function aftermath(text) {
    const marker = '|后续影响=';
    const start = text.indexOf(marker);
    const first = start + marker.length;
    if (start < 0 || text[first] !== '[') return null;
    let depth = 0, quoted = false, escaped = false;
    for (let i = first; i < text.length; i++) {
      const char = text[i];
      if (quoted) {
        if (escaped) escaped = false;
        else if (char === '\\') escaped = true;
        else if (char === '"') quoted = false;
      } else if (char === '"') quoted = true;
      else if (char === '[') depth++;
      else if (char === ']' && --depth === 0) {
        try { return {start, end:i+1, rows:JSON.parse(text.slice(first,i+1))}; }
        catch (_) { return null; }
      }
    }
    return null;
  }

  function summary(text) {
    if (typeof text !== 'string' || !text.startsWith(prefix)) return null;
    const result = field(text,'结果'), kind = field(text,'类型'), tail = field(text,'尾声');
    const allies = actors(text,'我方'), enemies = actors(text,'敌方');
    if (result === '胜' && kind !== '切磋' && tail === '击杀') {
      for (const enemy of enemies) if (enemy.state === '倒地不起') enemy.state = '已击杀';
    }
    const livingNames = new Set([...allies,...enemies].filter(row => row.state !== '已击杀').map(row => row.name));
    const deadNames = new Set(enemies.filter(row => row.state === '已击杀' && !livingNames.has(row.name)).map(row => row.name));
    const section = aftermath(text);
    const rows = (section?.rows || []).filter(row => row && (!injury(row) || !deadNames.has(row.人物)));
    const highlights = field(text,'关键',true).split(',').map(line=>line.trim()).filter(Boolean);
    return {result,tail,allies,enemies,rows,highlights,section};
  }

  function narrative(text) {
    const facts = summary(text);
    if (!facts) return text;
    let out = text;
    if (facts.section) {
      const fields = ['人物','类型','招式','长期后果','永久获得武学','起始熟练度','来源人物'];
      const rows = facts.rows.map(row => Object.fromEntries(fields.filter(key=>row[key]!==undefined).map(key=>[key,row[key]])));
      out = out.slice(0,facts.section.start)+(rows.length?'|后续影响='+JSON.stringify(rows):'')+out.slice(facts.section.end);
    }
    return out.replace(/\|(我方|敌方)=\[[^\]]*\]/g, (_, side) =>
      '|'+side+'=['+(side==='我方'?facts.allies:facts.enemies).map(row=>row.name+(row.state?':'+row.state:'')).join(';')+']');
  }

  return {executed,consequences,summary,narrative};
})();
const DLH_NARRATIVE_DISPLAY = (() => {
  const pick = (row, keys) => Object.fromEntries(keys.filter(key => row?.[key] !== undefined).map(key => [key, row[key]]));
  const localCompanion = new Set(['武学装配','调整武学','真意装配','装备定义','出战','休整']);

  function companion(row) {
    const fact = pick(row, ['标识','NPC标识','名称','类型']);
    const detail = pick(row.详情, ['方式','人物分类','人物键','已知境界','依据','装备','来源','去向','性质','物品','数量','原装备','现装备']);
    for (const key of ['原装备','现装备']) if (detail[key] === '空位') delete detail[key];
    if (Object.keys(detail).length) fact.详情 = detail;
    return fact;
  }

  function activity(row) {
    const out = pick(row, ['类型','来源','开始时辰','经过时辰','武学','导师','地点','起点','终点']);
    if (Array.isArray(row?.项目)) out.项目 = row.项目.map(item => pick(item, ['武学','时辰','导师']));
    return out;
  }

  function condition(row) {
    const result = {};
    for (const [name, current, limit] of [
      ['气血','气血','最大气血'], ['真气','真气条','最大真气条'],
      ['内力','内力值','最大内力值'], ['体力','耐力','最大耐力'],
    ]) {
      const value = row?.[current], max = row?.[limit];
      if (!Number.isFinite(value) || !Number.isFinite(max) || max <= 0) continue;
      const ratio = value / max;
      result[name] = ratio <= 0 ? (name === '气血' ? '已倒地' : '已耗尽')
        : ratio < .1 ? '所余无几' : ratio < .3 ? '所余不多' : ratio < .7 ? '已有损耗' : '尚足';
    }
    return result;
  }

  function battleReport(value) {
    return DLH_BATTLE_REPORT_DISPLAY.narrative(value);
  }

  function states(rows) {
    return Object.fromEntries(Object.entries(rows).map(([key, row]) => [key, pick(row, ['显示名称','来源','属性'])]));
  }

  return {companion, activity, condition, battleReport, states, isCompanionFact: row => !localCompanion.has(row?.类型)};
})();
var DLH_CRAFTING_NARRATIVE=(function(){
 'use strict';
 const cp=x=>JSON.parse(JSON.stringify(x)),obj=x=>x&&typeof x==='object'&&!Array.isArray(x),pick=(o,keys)=>Object.fromEntries(keys.filter(k=>o?.[k]!==undefined).map(k=>[k,cp(o[k])]));
 function active(j){
  const p=j.计划||{},r=p.recipe||{},out={标识:j.标识,名称:r.name,品级:r.grade,类型:r.kind,状态:j.状态,已投入:j.已投入,开始时辰:j.开始时辰};
  if (['锻造','回炉'].includes(r.kind)) return pick(out,['名称','类型','状态']);
   if(p.facility?.名称)out.炉具=p.facility.名称;
  if(Number.isFinite(p.work)&&Number.isFinite(j.操作进度))out.操作={已完成:j.操作进度,共需:p.work,剩余:Math.max(0,p.work-j.操作进度)};
  if(j.等待至!=null)out.等待至=j.等待至;
  let wasteRemaining=r.count||0;
  out.已备材料=(p.inputs||[]).map(x=>{const m=x.item?.制作材料||{},amount=x.count*(m.每件量??1);let used=j.已投入?amount:0;if(x.waste&&j.已投入){used=Math.min(amount,Math.max(0,wasteRemaining));wasteRemaining-=used;}return {库存批次:x.key,规格:x.spec||m.规格||m.原规格,库存件数:x.count,份数:amount,投入份数:used,未投入份数:amount-used};});
  if(r.facilityRequirements)out.工艺条件=cp(r.facilityRequirements);
  return out;
 }
 function project(input,view){
  const h=view?.主角;if(!obj(h))return;
  if(obj(h.制作)){
   const ongoing=Object.fromEntries(Object.entries(h.制作.任务||{}).filter(([,j])=>obj(j)&&['操作','等待'].includes(j.状态)).map(([id,j])=>[id,active(j)]));
   if(Object.keys(ongoing).length)h.制作={进行中:ongoing};else delete h.制作;
  }
  for(const row of Object.values(h.制作资料?.配方||{}))if(obj(row?.定义)){
   const r=row.定义;row.已知方案={名称:r.name,说明:r.description,类型:r.kind,品级:r.grade,部位:r.slot,种类:r.weapon,操作时辰:r.work,等待时辰:r.wait,产量:r.count,工艺条件:r.facilityRequirements,用料:(r.inputs||[]).map(x=>({规格:x.spec,份数:x.count,工序:x.role,金属:x.metal}))};delete row.定义;
  }
  for(const row of Object.values(h.制作资料?.配方||{}))if(row?.待核验定义!==undefined){row.待核验方案={名称:row.待核验定义?.name||'未命名方案',问题:row.校验问题||'工艺待核验'};delete row.待核验定义;}
  // Item revision arrays are generation history; the currently usable effect stays intact.
  for(const i of Object.values(h.物品栏||{}))if(obj(i))delete i.效用修订;
 }
 function owned(sd,d){
  const eq=sd?.主角?.装备栏||{},bag=sd?.主角?.物品栏||{};
  return (d.产物||[]).some(x=>{
   if(['物品','丹药','食物','材料'].includes(x.kind))return bag[x.key]?.名称===(d.成品?.名称||d.名称)||x.key===d.名称&&!!bag[x.key];
   return eq.装备库?.[x.key]?.名称===(d.成品?.名称||d.名称)||Object.values(eq).some(g=>obj(g)&&(g.同行标识===x.key||g.库存标识===x.key)&&g.名称===(d.成品?.名称||d.名称));
  });
 }

 // Completed business payloads contain only actual named products, never the plan.
 function compactItems(rows,kind){
  const groups=new Map();
  for(const x of rows){
   if(!obj(x)||typeof x.名称!=='string'||!x.名称||typeof x.品级!=='string'||!x.品级||!Number.isSafeInteger(x.数量)||x.数量<1||kind==='锻造'&&(typeof x.部位!=='string'||!x.部位))return null;
   const key=JSON.stringify(kind==='锻造'?[x.名称,x.部位,x.品级]:[x.名称,x.品级]),row=groups.get(key)||{名称:x.名称,...(kind==='锻造'?{部位:x.部位}:{}),品级:x.品级,数量:0};
   row.数量+=x.数量;if(!Number.isSafeInteger(row.数量))return null;groups.set(key,row);
  }
  return groups.size?[...groups.values()]:null;
 }
 function completedItems(e){
  const d=e?.数据;if(e?.类型!=='制作'||!obj(d)||!['锻造','炼丹'].includes(d.类型)||d.状态!=='完成')return null;
  if(Array.isArray(d.成品清单))return compactItems(d.成品清单,d.类型);
  if(!Array.isArray(d.产物))return null;
  const products=d.产物.filter(x=>x?.kind===(d.类型==='锻造'?'装备':'丹药'));
  // A stable product reference is an actual result; missing/duplicate identities
  // cannot be repaired using the recipe's planned yield.
  if(!products.length||products.some(x=>typeof x.key!=='string'||!x.key)||new Set(products.map(x=>x.key)).size!==products.length)return null;
  const items=Array.isArray(d.成品)?d.成品:[d.成品];if(items.length!==products.length)return null;
  const rows=items.map(item=>({名称:item?.名称,...(d.类型==='锻造'?{部位:item?.部位}:{}),品级:item?.品级||item?.评级,数量:d.类型==='炼丹'?item?.数量:1}));
  return compactItems(rows,d.类型);
 }
 function describe(e){
  const d=e.数据,items=completedItems(e);
  return items?d.类型+'完成 · '+items.reduce((n,x)=>n+x.数量,0)+(d.类型==='锻造'?'件':'颗')+' · '+items.map(x=>x.名称+'（'+[x.部位,x.品级].filter(Boolean).join(' / ')+(x.数量>1?' ×'+x.数量:'')+'）').join('、'):(d.名称||d.类型)+' · '+d.状态;
 }
 function wire(sd,e){
  const d=e.数据;
   if(e.类型==='同行')return DLH_NARRATIVE_DISPLAY.companion(d);
   if(e.类型==='行程')return DLH_NARRATIVE_DISPLAY.activity(d);
   if(e.类型==='战斗')return {...d,战报:DLH_NARRATIVE_DISPLAY.battleReport(d.战报)};
   if(e.类型==='制作'){
   if(['锻造','炼丹'].includes(d.类型)){
    const items=completedItems(e);if(items)return items;
     if(d.类型==='锻造')return pick(d,['名称','状态']);
    return {名称:d.名称||'名称未知',状态:d.状态||'状态未知',...(d.状态==='完成'?{说明:'成品信息待核验'}:d.工序阻碍?{说明:d.工序阻碍}:{})};
   }
   if(d.类型==='回炉')return pick(d,['名称','状态']);
   const out=pick(d,['标识','名称','品级','类型','状态','开始时辰','完成时辰','操作时辰','等待时辰','品质','已投入','工序阻碍','材料','产物']);
   if(d.设施?.名称)out.炉具=d.设施.名称;
   if(d.状态==='操作')out.操作={已完成:d.操作进度,共需:d.操作时辰};
   if(d.状态==='等待')out.等待至=d.等待至;
   const present=owned(sd,d);if(d.描述&&!present)out.描述=d.描述;
   if(d.成品){out.成品=pick(d.成品,['名称','评级','品级','类型','数量','部位','种类','效果说明','通用加成','定音','效用','使用限制','用途说明','规格','回收份数','剩余废料份数']);if(present)out.成品.详情='外观与用途见当前库存；此处为已结算制作结果，不再发放';else if(d.成品.描述)out.成品.描述=d.成品.描述;}
   if(Number.isFinite(d.操作进度))out.操作时辰=d.操作进度;
   if(typeof DLH_PRACTICE!=='undefined'){const gain=DLH_PRACTICE.gain(sd.主角,'制作/'+d.标识);if(gain>0)out.百艺实践={技艺:d.类型,经验:gain,已结算:true};}
   if(d.关联行程?.length)out.关联行程=d.关联行程.map(x=>pick(x,['标识','开始时辰','经过时辰','来源','类型']));
   return out;
  }
  if(e.类型==='精锻')return d.类型==='改名'?pick(d,['类型','原名','名称']):{};
  return cp(d);
 }
 function workshopActivity(sd,event){
  if(event?.类型!=='锻造'||typeof event.来源!=='string')return false;
  const matched=/^(装备精锻|定音精锻) (.+)$/.exec(event.来源);
  if(!matched)return false;
  return (sd?.主角?.制作?.精锻?.事件||[]).some(row=>row.类型==='精锻'&&row.请求===matched[2]&&
   event.开始时辰===row.起始时辰&&event.经过时辰===row.操作时辰);
 }
 return {project,wire,active,completedItems,compactItems,describe,workshopActivity};
})();

function dlhIsSocialRequest(request) {
  return request?.kind === 'social' || request?.kind == null && request?.type === 'social';
}

function dlhRetireSocialQueue(sd) {
  const queue = sd?.系统接入;
  if (!queue) return false;
  let changed = false;
  for (const [id, request] of Object.entries(queue.待办 || {})) {
    if (!dlhIsSocialRequest(request)) continue;
    delete queue.待办[id];
    if (queue.错误) delete queue.错误[id];
    changed = true;
  }
  for (const id of Object.keys(queue.错误 || {})) {
    if (id.startsWith('初识/') && !Object.hasOwn(queue.待办 || {}, id)) {
      delete queue.错误[id];
      changed = true;
    }
  }
  return changed;
}

function dlhNativeNarrativeView(input) {
  if(input===undefined)return {状态:'当前存档尚不可读，禁止猜写缺失事实'};
  const view=JSON.parse(JSON.stringify(input));
  const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
  const drop=(o,keys)=>{if(object(o))for(const k of keys)delete o[k];};
  const values=o=>object(o)?Object.values(o):[];
  // Current NPC values and pending/errors stay visible; settled receipts are bookkeeping.
  dlhRetireSocialQueue(view);
  drop(view.系统接入,['已办','好感','地理']);
  for(const group of values(view.登场人物))for(const npc of values(group))drop(npc,['初识判断']);
  // Narrative receives public capabilities, never the executable definition.
  // Full definitions remain in the actual MVU and dedicated generation inputs.
  const art=a=>{
    if(!object(a))return;
    const definition=a.战斗定义?.内容||a.战斗定义;
    if(Array.isArray(definition?.moves))a.已定义招式=definition.moves.map(m=>({名称:m.name||m.名称,解锁:m.tier||m.熟练度,...(m.description||m.desc?{说明:m.description||m.desc}:{})}));
    drop(a,['战斗定义']);
  };
  const gear=g=>{if(!object(g))return;drop(g,['面板加成','境界词条','精锻基准','原文指纹']);};
  const npc=n=>{
    if(!object(n))return;
    if(Array.isArray(n.武学表))n.武学表.forEach(art);
    drop(n,['建档配置','装备模板记录']);
    Object.entries(n.装备栏||{}).filter(([key])=>key!=='装备库').forEach(([,g])=>gear(g));
  };
  const h=view?.主角,w=view?.世界;
  if(object(h)) {
    drop(h.星命传承,['records','draw','nurture','battleReceipts']);
    drop(h.灵木培育,['请求','管控物品','已养护日']);
    drop(h.武学成长,['基准','账本','派生','来源历史','来源已初始化','每日训练']);
    drop(h.感悟成长,['基准','定义','账本','取值缓存','快照','百艺基准','百艺每日','见闻基准','心性基准']);
    drop(h.境界修行,['种子','账本','机缘快照','训练快照','阶段七窍基准','阶段养窍基准','阶段五脏基准']);
    values(h.武学与意境面板?.掌握武学).forEach(art);
    values(h.武学与意境面板?.领悟之意).forEach(art);
    for(const row of values(h.天赋体质)){
      if(!object(row))continue;
      const definition=row.能力定义?.内容||row.战斗定义?.内容;
      if(Array.isArray(definition?.招式))row.已定义招式=definition.招式.map(m=>({名称:m.name||m.名称,说明:m.description||m.desc||m.说明||''}));
      if(Array.isArray(definition?.成长方案))row.成长条件=definition.成长方案.map(p=>({阶段:p.阶段,条件:p.条件}));
      if(definition?.战斗悟学)row.悟学条件=JSON.parse(JSON.stringify(definition.战斗悟学));
      drop(row,['能力定义','战斗定义','定义记录']);
    }
    Object.entries(h.装备栏||{}).filter(([key])=>key!=='装备库').forEach(([,g])=>gear(g));
    values(h.装备栏?.装备库).forEach(gear);
    const p=h.战斗面板;
    drop(p,['基础基准','基础烘焙','资源缺口','上次资源']);
    drop(p,['基础属性','生效属性','常驻增益','装配被动','属性来源','三率来源']);
    drop(p?.日常恢复,['记录','余量']);
    // Drug use counts and active durations are gameplay constraints, not cache.
    drop(p?.消耗品,['已结算战斗']);
    DLH_CRAFTING_NARRATIVE.project(input,view);
  }
  if(object(w)) {
    drop(w,['正文回传','正文承接','战斗资料归档']);
    if(object(w.NPC战斗档案))w.已知战斗余量=Object.fromEntries(Object.entries(w.NPC战斗档案).map(([id,r])=>[id,{名称:r?.配置?.名称,境界:r?.配置?.境界,生死:r?.配置?.生死,...(object(r?.状态)?JSON.parse(JSON.stringify(r.状态)):{}),最近战斗:r?.最近战斗}]));
    drop(w,['武学战斗定义库','NPC生成记录','NPC战斗档案']);
    drop(w.日历,['消息处理','退休','普通退休终点','训练基准']);
    for(const a of values(w.日历?.活动))drop(a,['指纹']);
    const pending=new Set(w.日历?.待叙述||[]);
    if(pending.size){
     for(const key of pending){
      const e=w.日历.活动?.[key]?.事件||w.时间记录?.[key];
      if(!DLH_CRAFTING_NARRATIVE.workshopActivity(input,e))continue;
      pending.delete(key);
      if(w.时间记录)delete w.时间记录[key];
     }
     w.日历.待叙述=[...pending];
    }
    if(object(w.日历?.活动))for(const key of Object.keys(w.日历.活动))if(!pending.has(key))delete w.日历.活动[key];
    if(object(w.时间记录))for(const key of Object.keys(w.时间记录))if(input?.世界?.日历?.活动?.[key])delete w.时间记录[key];
    for(const m of values(w.同行?.成员))drop(m,['邀约指纹']);
  }
  for(const bs of [view?.战斗状态,h?.战斗状态]) {
    drop(bs,['引擎存档','引擎归档','结束记录','随机种子']);
    npc(bs?.敌方);
    for(const list of [bs?.我方队友,bs?.敌方队伍])if(Array.isArray(list))list.forEach(npc);
    // Keep all unacknowledged battle facts. A sent transcript is already in
    // message history; result/epilogue/participants/resources stay visible.
    if(object(bs)&&bs.阶段!=='进行中'&&bs.战报已发送===true)drop(bs,['战报','事件流']);
  }
  return view;
}



